const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=location.pathname.split('/')[1]==='en'?'en':'ar', user=null, csrf='', catalog={services:[],packages:[],settings:{},reviews:[]}, account=null, admin=null, adminTab='overview', bookingStep=1, bookingResult=null, filter='all';
const t=(ar,en)=>lang==='ar'?ar:en, name=o=>o?.['name_'+lang]||o?.name||'', desc=o=>o?.['description_'+lang]||'', money=v=>`${Number(v||0).toLocaleString(lang==='ar'?'ar-SA':'en-US')} ${t('ر.س','SAR')}`, minutes=v=>`${v||0} ${t('دقيقة','min')}`, href=r=>`/${lang}/${r}`, page=()=>{const p=location.pathname.split('/').slice(2).join('/')||'home';return p==='loyalty'?'petals':p};
let draft={service_ids:[],package_id:null,date:'',time:'',name:'',phone:'',neighborhood:'',notes:'',terms:false,idempotency_key:crypto.randomUUID()};
async function api(path,body){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.error||t('تعذر إتمام الطلب','Request failed'));return data}
const toast=m=>{const el=$('#toast');el.textContent=m;el.style.display='block';setTimeout(()=>el.style.display='none',4500)};
async function session(){const r=await api('/session');user=r.user;csrf=r.csrfToken;return r}
function go(route){history.pushState({},'',href(route));filter='all';render();window.scrollTo(0,0)}
function art(kind='spa',cls=''){const nails=kind==='nails'||kind==='gel';return `<div class="art ${cls}" aria-label="${t('رسم فني أصلي لمستلزمات السبا','Original spa still-life illustration')}" role="img"><svg viewBox="0 0 600 650" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="bg${kind}" x2="1" y2="1"><stop stop-color="${nails?'#e8ccd0':'#e1d9c7'}"/><stop offset="1" stop-color="#cbbcae"/></linearGradient><linearGradient id="b${kind}"><stop stop-color="#c49b65"/><stop offset=".45" stop-color="#e9c894"/><stop offset="1" stop-color="#ad8253"/></linearGradient><filter id="sh${kind}"><feGaussianBlur stdDeviation="13"/></filter></defs><rect width="600" height="650" fill="url(#bg${kind})"/><ellipse cx="310" cy="565" rx="235" ry="39" fill="#7c695d" opacity=".2" filter="url(#sh${kind})"/><path d="M0 40Q220 130 600 10V0H0" fill="#f7f0e4" opacity=".55"/><path d="M470 580Q400 330 520 60" fill="none" stroke="#6e7b55" stroke-width="6"/><g fill="#83916c"><ellipse cx="468" cy="380" rx="55" ry="17" transform="rotate(28 468 380)"/><ellipse cx="455" cy="315" rx="51" ry="16" transform="rotate(-30 455 315)"/><ellipse cx="472" cy="245" rx="58" ry="18" transform="rotate(32 472 245)"/><ellipse cx="483" cy="175" rx="48" ry="15" transform="rotate(-35 483 175)"/><ellipse cx="510" cy="99" rx="43" ry="14" transform="rotate(-58 510 99)"/></g><path d="M40 580Q90 380 40 230" fill="none" stroke="#8c9975" stroke-width="4"/><g fill="#9aa589"><ellipse cx="62" cy="400" rx="43" ry="14" transform="rotate(-30 62 400)"/><ellipse cx="41" cy="335" rx="43" ry="14" transform="rotate(36 41 335)"/></g><rect x="105" y="460" width="285" height="95" rx="40" fill="#f3ece0"/><path d="M145 480H350M140 500H350M147 522H340" stroke="#d9d0c1" fill="none" stroke-width="3" opacity=".5"/>${nails?'<rect x="210" y="290" width="100" height="170" rx="20" fill="#d2a5ac"/><rect x="225" y="210" width="70" height="100" rx="8" fill="#55434a"/><rect x="226" y="338" width="68" height="65" fill="#fbf7f4"/><text x="260" y="375" text-anchor="middle" fill="#503c45" font-family="Georgia" font-size="26">J</text><rect x="330" y="370" width="44" height="120" rx="20" fill="#b48b91" transform="rotate(25 330 370)"/>':'<rect x="210" y="270" width="117" height="218" rx="22" fill="url(#bspa)"/><rect x="230" y="225" width="77" height="58" rx="8" fill="#503f36"/><rect x="222" y="337" width="93" height="102" fill="#f7efdf"/><text x="268" y="380" text-anchor="middle" fill="#503c45" font-family="Georgia" font-size="29">J SPA</text><text x="268" y="408" text-anchor="middle" fill="#7c6d59" font-family="Arial" font-size="8" letter-spacing="2">BOTANICAL RITUAL</text><ellipse cx="380" cy="520" rx="70" ry="35" fill="#756b62"/><ellipse cx="385" cy="485" rx="53" ry="29" fill="#94887a"/><ellipse cx="379" cy="455" rx="37" ry="20" fill="#b0a292"/>'}<g fill="#e8c7c3"><ellipse cx="160" cy="410" rx="30" ry="11" transform="rotate(-35 160 410)"/><ellipse cx="153" cy="411" rx="30" ry="11" transform="rotate(35 153 411)"/><ellipse cx="159" cy="411" rx="30" ry="11" transform="rotate(90 159 411)"/></g><circle cx="159" cy="411" r="8" fill="#c3a477"/></svg><span class="art-caption">J SPA · ${t('تكوين فني','ORIGINAL STILL LIFE')}</span></div>`}
function header(){return `<div class="announcement">${t('سبا نسائي منزلي · المدينة المنورة · لحظة تستحقينها','WOMEN’S HOME SPA · MADINAH · A MOMENT, JUST FOR YOU')}</div><header class="wrap header"><a class="brand" href="${href('home')}">J SPA<small>THE ART OF SLOW BEAUTY</small></a><nav class="nav" id="nav">${[['home','الرئيسية','Home'],['services','خدماتنا','Our rituals'],['packages','الباقات','Packages'],['petals','نادي بتلات J','J Petals Club'],['about','عن J','Our story']].map(([r,a,e])=>`<a href="${href(r)}" class="${page()===r?'active':''}">${t(a,e)}</a>`).join('')}</nav><div class="header-tools"><button class="lang" id="language">${t('EN','عربي')}</button><a href="${href(user?'account':'login')}" aria-label="${t('حسابي','My account')}">${t('حسابي','Account')}</a><a class="btn small" href="${href('booking')}">${t('احجزي لحظتكِ','Book your moment')}</a><button class="menu" id="menu" aria-label="Menu" aria-expanded="false">☰</button></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="${href('home')}">J SPA</a><p>${t('لحظتكِ الخاصة… في راحة بيتكِ','Your Moment of Beauty, At Home.')}<br>${t('سبا نسائي منزلي في المدينة المنورة','Women’s home spa in Madinah')}</p></div><div class="footer-links">${[['services','الخدمات','Services'],['packages','الباقات','Packages'],['booking','طلب موعد','Request an appointment'],['reviews','تجارب العميلات','Customer reviews'],['faq','الأسئلة الشائعة','FAQ']].map(([r,a,e])=>`<a href="${href(r)}">${t(a,e)}</a>`).join('')}</div><div class="footer-links">${[['contact','تواصلي معنا','Contact'],['policies','سياسة الحجز','Booking policies'],['privacy','الخصوصية','Privacy'],['terms','الشروط','Terms'],['admin','دخول الموظفات','Staff access']].map(([r,a,e])=>`<a href="${href(r)}">${t(a,e)}</a>`).join('')}${['instagram','tiktok'].filter(k=>safeURL(catalog.settings[k])).map(k=>`<a href="${esc(catalog.settings[k])}" target="_blank" rel="noopener noreferrer">${k}</a>`).join('')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} J SPA</span><span>${t('بكل عناية، لكِ.','Thoughtfully, for you.')}</span></div></div></footer>`}
function safeURL(s){try{return ['https:','http:'].includes(new URL(s).protocol)}catch{return false}}
const head=(title,sub='')=>`<div class="page-head"><span class="eyebrow">J SPA · MADINAH</span><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>`;
const provisional=()=>catalog.settings.business_approved?'':`<div class="notice">${t('الأسعار والباقات تقديرية لحين اعتمادها من إدارة J SPA. طلب الموعد لا يعني تأكيد الحجز.','Prices and packages are provisional pending business approval. An appointment request is not a confirmed booking.')}</div>`;
function serviceCard(s){return `<article class="card service-card">${serviceArt(s)}<h3><a href="${href('services/'+s.id)}">${esc(name(s))}</a></h3><p>${esc(desc(s))}</p><div class="card-meta"><span>${minutes(s.duration)}</span><span>${money(s.price)}</span></div><a class="btn light" href="${href('booking')}?service=${s.id}">${t('اختاري هذه اللحظة','Choose this ritual')} <span aria-hidden="true">${t('←','→')}</span></a></article>`}
function packageCard(p,i){return `<article class="package"><span class="number">0${i+1}</span><h3>${esc(name(p))}</h3><p class="muted">${(p.service_ids||[]).map(id=>esc(name(catalog.services.find(s=>s.id==id)))).join(' + ')}</p><p>${minutes(p.duration)}</p><p class="price">${money(p.price)} <del>${money(p.original_total)}</del></p><a class="btn light" href="${href('booking')}?package=${p.id}">${t('اختاري الباقة','Choose package')}</a></article>`}
function home(){return `<main id="main"><div class="wrap"><section class="hero"><div class="hero-copy"><span class="eyebrow">${t('طقوس جمال، تصل إلى بابكِ','BEAUTY RITUALS, BROUGHT HOME')}</span><h1>${t('لحظتكِ الخاصة…<br>في راحة بيتكِ','A little stillness.<br>A lot of you.')}</h1><p>${t('اتركي إيقاع يومكِ خلفكِ. عناية هادئة، وتفاصيل مدروسة، ومساحة لكِ وحدكِ — في منزلكِ بالمدينة المنورة.','Let the day soften around you. Thoughtful spa and nail rituals, brought to the comfort of your home in Madinah.')}</p><div class="hero-actions"><a class="btn" href="${href('booking')}">${t('احجزي لحظتكِ','Find your moment')} <span aria-hidden="true">${t('←','→')}</span></a><a class="text-link" href="${href('services')}">${t('اكتشفي خدماتنا','Explore our rituals')}</a></div><p class="hero-note">${t('للسيدات فقط · مواعيد بتأكيد شخصي من فريقنا','EXCLUSIVELY FOR WOMEN · PERSONALLY CONFIRMED')}</p></div><div class="hero-visual">${art('spa','hero-art')}<div class="seal">${t('عناية<br>على مهل','SLOW DOWN<br>BLOOM AGAIN')}</div></div></section><div class="benefits"><span>${t('عناية في راحة منزلكِ','Comfort of your home')}</span><span>${t('تجربة مصممة لكِ','Thoughtfully personal')}</span><span>${t('لمسات صغيرة، شعور أجمل','Little details, lovely moments')}</span></div><section class="section"><div class="section-head"><div><span class="eyebrow">${t('اختاري طقسكِ','YOUR RITUAL, YOUR WAY')}</span><h2>${t('مساحة للعناية بكِ','Make room for yourself')}</h2></div><a class="text-link" href="${href('services')}">${t('جميع الخدمات ←','All rituals →')}</a></div><div class="grid">${[catalog.services[0],catalog.services[4],catalog.services[8]].filter(Boolean).map(serviceCard).join('')}</div></section><section class="section" style="padding-top:0"><div class="section-head"><div><span class="eyebrow">${t('لحظات متناغمة','BEAUTIFULLY PAIRED')}</span><h2>${t('باقات تجمع ما تحبين','More of what you love')}</h2></div><a class="text-link" href="${href('packages')}">${t('كل الباقات ←','All packages →')}</a></div>${provisional()}<div class="grid packages-grid">${catalog.packages.slice(0,3).map(packageCard).join('')}</div></section><section class="loyalty-band"><div><span class="eyebrow">J PETALS CLUB</span><h2>${t('كل زيارة…<br>بتلة جديدة لكِ','Every visit.<br>A little more bloom.')}</h2><p>${t('اجمعي البتلات بعد زياراتكِ المكتملة والمدفوعة، واستبدليها بمكافآت تزيد لحظاتكِ جمالاً.','Collect petals after completed, verified-paid visits. Turn your moments of care into rewards to enjoy next time.')}</p><a class="text-link" href="${href('petals')}">${t('تعرّفي على نادي بتلات J ←','Discover J Petals Club →')}</a></div><div class="loyalty-card"><span class="eyebrow">J SPA · PETALS CLUB</span><h3>${t('جمالكِ يزهر، بتلةً بتلة','Beauty blooms, petal by petal')}</h3><div class="petals">${Array.from({length:6},(_,i)=>`<span class="petal ${i>3?'unfilled':''}"></span>`).join('')}</div><p class="muted">${t('رسم توضيحي للبرنامج، وليس رصيد حساب','Program illustration, not an account balance')}</p><div class="row"><span>${t('١ ر.س = ١ بتلة افتراضياً','Default: 1 SAR = 1 petal')}</span><span>J</span></div></div></section><section class="section"><div class="section-head"><h2>${t('من اختياركِ… إلى بابكِ','From a wish to your doorstep')}</h2></div><div class="steps">${[['01','اختاري لحظتكِ','Choose your ritual','خدمات وباقات تناسب ما تحتاجينه اليوم.','Find the care you feel like today.'],['02','اطلبي موعدكِ','Request a moment','حددي الوقت المفضل، ثم تواصلي عبر واتساب.','Share your preferred time, then connect on WhatsApp.'],['03','نؤكد التفاصيل معكِ','We make it personal','يراجع فريقنا الموعد ويؤكده معكِ شخصياً.','Our team reviews your request and confirms it with you.']].map(([n,a,e,b,f])=>`<div><span class="step-num">${n}</span><h3>${t(a,e)}</h3><p class="muted">${t(b,f)}</p></div>`).join('')}</div></section><section style="padding-bottom:65px"><div class="section-head"><h2>${t('كلمات من لحظات حقيقية','Words from real moments')}</h2></div>${reviewsContent(catalog.reviews)}</section></div><section class="cta"><span class="eyebrow">${t('خذي نفساً. هذه لحظتكِ.','TAKE A BREATH. THIS IS YOUR MOMENT.')}</span><h2>${t('القليل من الهدوء، الكثير منكِ','Your moment is waiting.')}</h2><a class="btn" href="${href('booking')}">${t('ابدئي طلب الحجز','Request your appointment')}</a></section></main>`}
function reviewsContent(reviews=[]){return reviews.length?`<div class="grid">${reviews.map(r=>`<article class="card"><div class="stars" aria-label="${r.rating} / 5">${'★'.repeat(r.rating)}</div><p>${esc(r.body)}</p><span class="muted">${esc(r.display_name||t('عميلة J SPA','J SPA guest'))} · ${t('زيارة موثقة','Verified visit')}</span></article>`).join('')}</div>`:`<div class="empty"><h3>${t('نترك المساحة لتجربتكِ','A space for your experience')}</h3><p class="muted">${t('ستظهر هنا آراء العميلات بعد زيارات مكتملة ومراجعة النشر. لا توجد تقييمات منشورة بعد.','Reviews from completed visits will appear here after moderation. No reviews have been published yet.')}</p></div>`}
function services(){return `<main id="main" class="wrap">${head(t('طقوس العناية بكِ','Your rituals of care'),t('من هدوء المساج إلى أناقة التفاصيل.','From a quiet massage to the finishing touches.'))}${provisional()}<div class="filter">${[['all','جميع الخدمات','All rituals'],['massage','المساج','Massage'],['nails','الأظافر','Nail care'],['gel','الجل','Gel']].map(([id,a,e])=>`<button class="${filter===id?'active':''}" data-filter="${id}">${t(a,e)}</button>`).join('')}</div><div class="grid section" style="padding-top:0">${catalog.services.filter(s=>filter==='all'||s.category===filter).map(serviceCard).join('')}</div></main>`}
function detail(id){const s=catalog.services.find(x=>x.id==id);if(!s)return notFound();return `<main id="main" class="wrap">${head(esc(name(s)))}<div class="split section" style="padding-top:0">${serviceArt(s,'detail-art')}<div><span class="eyebrow">${minutes(s.duration)} · ${money(s.price)}</span><h2>${t('وقت لكِ، بكل عناية','Time for you, thoughtfully')}</h2><p>${esc(desc(s))}</p><h3>${t('تشمل الزيارة','Your visit includes')}</h3><p class="muted">${t('الخدمة المختارة في منزلكِ، وتجهيز المستلزمات اللازمة، وتنسيق التفاصيل مسبقاً مع الفريق.','Your selected service at home, the necessary supplies, and details coordinated with our team beforehand.')}</p>${/therap|lymph/i.test(s.name_en)?`<div class="notice">${t('هذه الخدمة تتطلب اعتماد المؤهلات والاحتياطات المهنية من الإدارة قبل تقديمها. لا تعد بديلاً للاستشارة الطبية.','Professional credentials and precautions require business approval before this service can be delivered. This is not a substitute for medical advice.')}</div>`:''}${provisional()}<a class="btn" href="${href('booking')}?service=${s.id}">${t('اطلبي هذه الخدمة','Request this ritual')}</a><p class="muted">${t('الموعد المفضل يخضع لتأكيد الفريق.','Preferred times are subject to team confirmation.')}</p></div></div><section class="section"><h2>${t('لحظات أخرى لكِ','A little more care')}</h2><div class="grid">${catalog.services.filter(x=>x.category===s.category&&x.id!==s.id).slice(0,3).map(serviceCard).join('')}</div></section></main>`}
function field(label,key,type='text',value='',extra=''){return `<label class="field">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selected(){const p=catalog.packages.find(p=>p.id==draft.package_id);const services=p?(p.service_ids||[]).map(id=>catalog.services.find(s=>s.id==id)).filter(Boolean):catalog.services.filter(s=>draft.service_ids.includes(String(s.id))||draft.service_ids.includes(s.id));return {items:services,total:p?p.price:services.reduce((a,s)=>a+Number(s.price),0),duration:p?p.duration:services.reduce((a,s)=>a+Number(s.duration),0),package:p}}
function summary(){const s=selected();return `<aside class="summary"><span class="eyebrow">${t('لحظتكِ المختارة','YOUR CHOSEN MOMENT')}</span><h3>${s.package?esc(name(s.package)):t('ملخص الطلب','Request summary')}</h3>${s.items.length?s.items.map(x=>`<div class="summary-line"><span>${esc(name(x))}</span><span>${money(x.price)}</span></div>`).join(''):`<p class="muted">${t('اختاري خدمة أو باقة للبدء.','Choose a ritual or package to begin.')}</p>`}<div class="summary-line"><span>${t('المدة التقديرية','Estimated duration')}</span><span>${minutes(s.duration)}</span></div><div class="summary-line summary-total"><span>${t('الإجمالي','Total')}</span><span>${money(s.total)}</span></div><p class="muted">${t('الوقت المفضل ليس حجزاً مؤكداً. جميع المواعيد بتأكيد شخصي.','Your preferred time is a request. All appointments are personally confirmed.')}</p></aside>`}
function booking(){if(bookingResult)return bookingSuccess();return `<main id="main" class="wrap">${head(t('لنصنع لحظتكِ','Let’s make it your moment'),t('طلب بسيط. تأكيد شخصي. عناية تصل إليكِ.','A simple request. A personal confirmation. Care that comes to you.'))}<div class="booking-layout"><div class="booking-main"><div class="progress">${[t('الخدمة','Ritual'),t('الموعد','Time'),t('بياناتكِ','Details'),t('المراجعة','Review')].map((n,i)=>`<span class="${i+1<=bookingStep?'current':''}">${i+1} · ${n}</span>`).join('')}</div><form id="booking-form"><div id="form-error" role="alert"></div>${bookingStep===1?`<h3>${t('ما الذي تحتاجينه اليوم؟','What feels right today?')}</h3><div class="tabs"><button type="button" data-booktype="services" class="${!draft.package_id?'active':''}">${t('الخدمات','Services')}</button><button type="button" data-booktype="packages" class="${draft.package_id?'active':''}">${t('الباقات','Packages')}</button></div>${catalog.services.map(s=>`<label class="selection"><input type="checkbox" name="service" value="${s.id}" ${draft.service_ids.map(String).includes(String(s.id))?'checked':''}><span><strong>${esc(name(s))}</strong><small>${minutes(s.duration)}</small></span><span class="amount">${money(s.price)}</span></label>`).join('')}<h3 style="margin-top:30px">${t('أو اختاري باقة','Or choose a package')}</h3>${catalog.packages.map(p=>`<label class="selection"><input type="radio" name="package" value="${p.id}" ${draft.package_id==p.id?'checked':''}><span>${esc(name(p))}<small>${minutes(p.duration)}</small></span><span class="amount">${money(p.price)}</span></label>`).join('')}`:bookingStep===2?`<h3>${t('متى تفضلين زيارتنا؟','When would you like us to visit?')}</h3><div class="notice">${t('الأوقات هي تفضيلات فقط؛ سيتواصل الفريق لتأكيد التوفر. التوقيت: الرياض.','Times are preferences only; our team will confirm availability. Time zone: Riyadh.')}</div><div class="form-grid">${field(t('التاريخ المفضل','Preferred date'),'date','date',draft.date,'required min="'+new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'"')}${field(t('الوقت المفضل','Preferred time'),'time','time',draft.time,'required')}</div><label class="field">${t('الحي في المدينة المنورة','Madinah neighborhood')}${catalog.settings.areas?.length?`<select name="neighborhood" required><option value="">${t('اختاري الحي','Select neighborhood')}</option>${catalog.settings.areas.map(a=>`<option ${draft.neighborhood===a?'selected':''}>${esc(a)}</option>`).join('')}</select>`:`<input name="neighborhood" value="${esc(draft.neighborhood)}" required maxlength="100">`}</label>`:bookingStep===3?`<h3>${t('نتعرّف عليكِ','A few details about you')}</h3><div class="form-grid">${field(t('الاسم','Name'),'name','text',draft.name||user?.name||'','required autocomplete="name" maxlength="100"')}${field(t('رقم الجوال السعودي','Saudi mobile number'),'phone','tel',draft.phone||user?.phone||'','required autocomplete="tel" placeholder="05xxxxxxxx"')}</div><label class="field">${t('ملاحظات اختيارية','Optional notes')}<textarea name="notes" maxlength="1000">${esc(draft.notes)}</textarea></label>${!user?`<p class="muted">${t('يمكنكِ إكمال الحجز كزائرة. أنشئي حساباً لاحقاً لمتابعة زياراتكِ.','You can book as a guest. Create an account later to keep future visits together.')}</p>`:''}`:`<h3>${t('راجعي تفاصيل لحظتكِ','Review your moment')}</h3><div class="card"><p>${esc(draft.name)} · <bdi>${esc(draft.phone)}</bdi></p><p>${esc(draft.date)} · ${esc(draft.time)} (${t('الرياض','Riyadh')})</p><p>${esc(draft.neighborhood)}</p>${draft.notes?`<p>${esc(draft.notes)}</p>`:''}</div><label class="check"><input type="checkbox" name="terms" required ${draft.terms?'checked':''}><span>${t('أوافق على','I agree to the')} <a class="text-link" href="${href('policies')}" target="_blank">${t('سياسة الحجز','booking policies')}</a> ${t('و','and')} <a class="text-link" href="${href('privacy')}" target="_blank">${t('الخصوصية','privacy notice')}</a>. ${t('أفهم أن الموعد ينتظر تأكيد الفريق.','I understand the appointment awaits staff confirmation.')}</span></label>${provisional()}`}<div class="form-actions">${bookingStep>1?`<button type="button" class="btn light" id="back-step">${t('السابق','Back')}</button>`:'<span></span>'}<button class="btn" type="submit">${bookingStep===4?t('تسجيل طلب الحجز','Submit appointment request'):t('متابعة','Continue')}</button></div></form></div>${summary()}</div></main>`}
function bookingSuccess(){return `<main id="main" class="wrap">${head(t('لحظتكِ أقرب الآن','Your moment is a little closer'))}<div class="content"><div class="success"><h3>${t('تم تسجيل طلبكِ، وسيتم تأكيد الموعد بعد مراجعته مع فريق J Spa.','Your request is saved. J SPA will review and personally confirm your appointment.')}</h3><p>${t('رقم الطلب','Reference')}: <bdi>${esc(bookingResult.booking?.reference)}</bdi></p><span class="badge pending">${t('بانتظار التأكيد','Pending confirmation')}</span></div><p>${t('افتحي واتساب ثم اضغطي إرسال بنفسكِ. فتح الرابط لا يعني إرسال الرسالة أو تأكيد الحجز.','Open WhatsApp and press Send yourself. Opening the link does not send the message or confirm the booking.')}</p>${bookingResult.whatsapp_url?`<a class="btn sage" href="${esc(bookingResult.whatsapp_url)}" target="_blank" rel="noopener">${t('فتح واتساب','Open WhatsApp')}</a>`:`<div class="notice">${t('لم تضف الإدارة رقم واتساب بعد. طلبكِ محفوظ ويمكن للفريق مراجعته.','The business has not configured its WhatsApp number yet. Your request is saved for staff review.')}</div>`}<button class="btn light" id="copy-message">${t('نسخ الرسالة','Copy message')}</button><pre>${esc(bookingResult.message)}</pre><button id="new-booking" class="btn light">${t('طلب حجز جديد','Start a new request')}</button> <a class="text-link" href="${href('account')}">${t('حسابي','My account')}</a></div></main>`}
function auth(mode='login'){return `<main id="main" class="wrap"><div class="auth"><span class="eyebrow">WELCOME TO J SPA</span><h2>${mode==='register'?t('مساحتكِ الخاصة','Your own little space'):mode==='reset'?t('كلمة مرور جديدة','A fresh password'):t('أهلاً بعودتكِ','A lovely welcome back')}</h2><p class="muted">${t('تابعي مواعيدكِ وبتلاتكِ من مكان واحد.','Your appointments and petals, all together.')}</p><form id="auth-form" data-mode="${mode}"><div id="form-error" role="alert"></div>${mode==='register'?field(t('الاسم','Name'),'name','text','','required autocomplete="name"'):''}${mode!=='reset'?field(t('رقم الجوال السعودي','Saudi mobile number'),'phone','tel','','required autocomplete="tel" placeholder="05xxxxxxxx"'):field(t('رمز الاستعادة من الفريق','Recovery token from staff'),'token','text',new URLSearchParams(location.search).get('token')||decodeURIComponent(location.hash.slice(1))||'','required')}${field(t('كلمة المرور','Password'),'password','password','','required minlength="12" autocomplete="'+(mode==='login'?'current-password':'new-password')+'"')}${mode==='register'?`${field(t('تأكيد كلمة المرور','Confirm password'),'passwordConfirmation','password','','required minlength="12" autocomplete="new-password"')}<label class="check"><input type="checkbox" name="terms" required><span>${t('أوافق على الشروط وسياسة الخصوصية.','I agree to the terms and privacy notice.')} <a class="text-link" href="${href('terms')}">${t('اقرئي الشروط','Read terms')}</a></span></label>`:''}<button class="btn" type="submit">${mode==='register'?t('إنشاء حساب','Create account'):mode==='reset'?t('حفظ كلمة المرور','Save password'):t('تسجيل الدخول','Sign in')}</button></form><p class="muted" style="margin-top:20px">${mode==='login'?`<a class="text-link" href="${href('register')}">${t('جديدة هنا؟ أنشئي حساباً','New here? Create an account')}</a><br><a href="${href('recovery')}">${t('نسيتِ كلمة المرور؟','Forgot your password?')}</a>`:`<a class="text-link" href="${href('login')}">${t('تسجيل الدخول','Sign in')}</a>`}</p></div></main>`}
function status(s){return ({pending_confirmation:t('بانتظار التأكيد','Pending confirmation'),confirmed:t('مؤكد','Confirmed'),in_progress:t('قيد التنفيذ','In progress'),completed:t('مكتمل','Completed'),cancelled:t('ملغي','Cancelled'),no_show:t('لم تحضر','No show')})[s]||esc(s)}
function bookingCard(b){return `<article class="booking-card"><div class="row"><h3>${esc(b.reference)}</h3><span class="badge ${b.status==='pending_confirmation'?'pending':''}">${status(b.status)}</span></div><p class="muted">${esc(b.date)} · ${esc(b.time)} · ${esc(b.neighborhood)}</p><p>${(b.items||[]).map(i=>esc(name(i)||i.name)).join(' · ')}</p><div class="row"><span>${money(b.total)}</span>${b.status==='completed'&&!account?.reviews?.some(r=>r.booking_id===b.id)?`<button class="btn small light" data-review="${b.id}">${t('اكتبي تجربتكِ','Share your experience')}</button>`:''}</div></article>`}
function petalsContent(){const rewards=account?.rewards||catalog.settings.rewards||[{id:'r200',points:200,value:10},{id:'r500',points:500,value:30}];return `<div class="loyalty-band"><div><span class="eyebrow">J PETALS CLUB</span><h2>${t('نادي بتلات J','A little more bloom')}</h2><p>${t('نحتفي بلحظات العناية التي تختارينها لنفسكِ. تُضاف النقاط بعد اكتمال الخدمة والتحقق من الدفع وملكية الحساب.','A little thank-you for choosing time for yourself. Points are issued after service completion, verified payment and account ownership verification.')}</p><p class="muted">${t('النقاط تُحسب على المبلغ المؤهل المدفوع بعد الخصومات، مع التقريب للأسفل.','Points are calculated on eligible paid spend after discounts, rounded down.')}</p></div><div class="loyalty-card"><span class="eyebrow">${t('رصيد البتلات','YOUR PETAL BALANCE')}</span><h2>${account&&user?.verified?Number(account.balance||0).toLocaleString(): '—'}</h2><div class="petals">${Array.from({length:6},(_,i)=>`<span class="petal ${!account||i>=Math.min(6,Math.floor((account.balance||0)/200*6))?'unfilled':''}"></span>`).join('')}</div><p class="muted">${account?t('تُراجع طلبات المكافآت بواسطة الفريق.','Reward requests are reviewed by our team.'):t('سجلي الدخول لمشاهدة رصيدكِ الحقيقي.','Sign in to view your actual balance.')}</p>${!user?`<a class="btn light" href="${href('register')}">${t('انضمي للنادي','Join the club')}</a>`:''}</div></div><div class="grid two section">${rewards.map(r=>`<article class="card"><span class="eyebrow">${r.points} ${t('بتلة','PETALS')}</span><h3>${t('مكافأة بقيمة','A reward of')} ${money(r.value)}</h3><p class="muted">${t('خصم يطبّق على حجز مؤهل بعد مراجعة الفريق.','A discount applied to an eligible booking after staff review.')}</p>${account&&user?.verified?`<button class="btn light" data-reward="${esc(r.id)}" ${account.balance<r.points?'disabled':''}>${t('طلب المكافأة','Request reward')}</button>`:''}</article>`).join('')}</div>`}
async function accountPage(section){if(!user)return auth();if(!account){account=await api('/account')}return `<main id="main" class="wrap">${head(t('أهلاً، ','Hello, ')+esc(user.name))}<div class="account-grid"><aside class="side-nav"><h3>${t('مساحتكِ','Your space')}</h3><span class="muted"><bdi>${esc(user.phone)}</bdi></span>${[['account','نظرة عامة','Overview'],['bookings','حجوزاتي','My bookings'],['rewards','بتلاتي ومكافآتي','Petals & rewards']].map(([r,a,e])=>`<a href="${href(r)}">${t(a,e)}</a>`).join('')}<button class="btn light small" id="logout">${t('تسجيل الخروج','Sign out')}</button></aside><div class="dashboard-content">${!user.verified?`<div class="notice"><h3>${t('لنكمل توثيق رقمكِ','Let’s verify your number')}</h3><p>${t('رقمكِ لم يُوثق بعد. أرسلي مرجع التحقق عبر واتساب، وسيطابق الفريق رقم المرسلة مع حسابكِ قبل التوثيق.','Your number is not verified yet. Send the verification reference through WhatsApp; staff will check the sender’s number against your account.')}</p><button class="btn small" id="verify-request">${t('تأكيد رقم الجوال عبر واتساب','Verify number through WhatsApp')}</button><div id="verification-result"></div></div>`:''}${section==='rewards'?petalsContent()+ledgerTable(account.ledger)+`<h3>${t('طلبات المكافآت','Reward requests')}</h3>`+simpleTable(account.reward_requests||[],['id','status','points','value']):`<h2>${t('زياراتكِ','Your visits')}</h2>${account.bookings?.length?account.bookings.map(bookingCard).join(''):`<div class="empty"><h3>${t('لحظتكِ الأولى تبدأ هنا','Your first moment starts here')}</h3><p class="muted">${t('لا توجد حجوزات مرتبطة بحسابكِ. حجوزات الزائرات لا ترتبط تلقائياً برقم الجوال.','No bookings are linked to your account. Guest bookings are never linked automatically by phone number.')}</p><a class="btn" href="${href('booking')}">${t('اطلبي موعداً','Request an appointment')}</a></div>`}`}</div></div></main>`}
function ledgerTable(rows=[]){return `<h3>${t('سجل البتلات','Petal history')}</h3>${simpleTable(rows,['created_at','points','reason','booking_id'])}`}
function simpleTable(rows,keys){return rows.length?`<div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(label(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty muted">${t('لا توجد سجلات بعد.','No records yet.')}</div>`}
function label(k){return ({id:t('المرجع','Reference'),created_at:t('التاريخ','Date'),points:t('البتلات','Points'),reason:t('السبب','Reason'),booking_id:t('الحجز','Booking'),status:t('الحالة','Status'),value:t('القيمة','Value'),name:t('الاسم','Name'),phone:t('الجوال','Phone'),verified:t('موثق','Verified'),role:t('الدور','Role'),amount:t('المبلغ','Amount'),payment_method:t('طريقة الدفع','Payment method'),action:t('الإجراء','Action'),actor_id:t('الموظفة','Actor'),details:t('التفاصيل','Details')})[k]||k.replaceAll('_',' ')}
function contentPage(p){const pages={about:[t('عناية تُشبهكِ','Care that feels like you'),t('J SPA مساحة هادئة للعناية والجمال في منزلكِ بالمدينة المنورة. نؤمن أن التفاصيل الصغيرة تمنح لحظتكِ معنا معناها: وقت مخصص لكِ، وتواصل شخصي، وخيارات واضحة.','J SPA brings a quiet moment of beauty and care to your home in Madinah. Our approach is thoughtful: time for you, personal communication, and clearly presented choices.'),t('خدماتنا مخصصة للسيدات. يتم تنسيق كل زيارة وتأكيدها مع الفريق قبل الموعد.','Our services are exclusively for women. Every visit is coordinated and confirmed personally with the team.')],policies:[t('سياسة الحجز','Booking policies'),t('تسجيل الطلب لا يؤكد الموعد. يراجع الفريق الوقت المطلوب ومنطقة الخدمة والطاقة الاستيعابية ثم يتواصل معكِ لتأكيد التفاصيل.','Submitting a request does not confirm an appointment. Staff review the preferred time, service area and capacity before agreeing the details with you.'),t('الأسعار والمدد الحالية تقديرية حتى اعتماد الإدارة. يتم الاتفاق على أي تعديل قبل تقديم الخدمة. للتعديل أو الإلغاء تواصلي مع الفريق؛ لا توجد رسوم إلغاء معتمدة حالياً في هذه النسخة.','Current prices and durations are provisional until approved. Any changes must be agreed before service. Contact the team to reschedule or cancel; no cancellation fee has been approved in this version.')],privacy:[t('خصوصيتكِ تهمنا','Your privacy matters'),t('نستخدم الاسم ورقم الجوال والحي وبيانات الموعد لتنسيق الخدمات وإدارة الحساب والمكافآت. لا ننشر رقم جوالكِ أو معلومات الحجز. الآراء المنشورة تعرض الاسم الاختياري والتقييم والنص فقط.','We use your name, mobile number, neighborhood and appointment details to coordinate services and manage your account and rewards. Your phone number and booking details are not published. Public reviews show only the optional display name, rating and review text.'),t('نحفظ كلمات المرور بصيغة مشتقة آمنة ولا يطّلع الموظفون عليها. عند الانتقال إلى واتساب تخضع الرسالة لسياسة واتساب. لا نستخدم بياناتكِ للتسويق دون موافقتكِ المناسبة. تواصلي مع الإدارة لطلبات الوصول أو التصحيح أو الحذف.','Passwords are securely derived; employees cannot read them. Messages opened in WhatsApp are subject to WhatsApp’s policies. We do not use your details for marketing without appropriate consent. Contact management for access, correction or deletion requests.'),t('مسودة تحتاج اعتماد الإدارة: يجب تحديد الجهة المسؤولة ووسيلة تواصل الخصوصية ومكان الاستضافة ومدد الاحتفاظ وإجراءات حقوق أصحاب البيانات قبل الإطلاق. لا تعد هذه الصفحة إقراراً بالامتثال القانوني.','Draft requiring business approval: identify the data controller, privacy contact, hosting location, retention periods and data-rights procedures before launch. This page does not claim legal compliance.')],terms:[t('الشروط والأحكام','Terms of service'),t('الخدمات المنزلية مخصصة للسيدات في مناطق الخدمة المعتمدة بالمدينة المنورة. إرسال الطلب يعني طلب تواصل فقط؛ لا ينشئ موعداً مؤكداً.','Home services are for women within approved Madinah service areas. Submitting a request asks the team to contact you; it does not create a confirmed appointment.'),t('النقاط تُحتسب بعد اكتمال الخدمة والتحقق من الدفع وملكية الحساب. المكافآت تخضع للتحقق وتُستخدم مرة واحدة، وقد تُعدل النقاط عند الاسترداد. لا تُصرف النقاط نقداً.','Points are awarded only after completed service, verified payment and account ownership checks. Rewards are reviewed, used once, and points may be adjusted for refunds. Points cannot be exchanged for cash.'),t('الشروط النهائية وشروط الإلغاء والاحتياطات المهنية تحتاج اعتماد الإدارة قبل الإطلاق.','Final terms, cancellation conditions and professional precautions require business approval before launch.')]};const d=pages[p];if(catalog.settings[p+'_'+lang])d.splice(1,d.length-1,catalog.settings[p+'_'+lang]);return `<main id="main" class="wrap">${head(d[0])}<div class="content">${d.slice(1).map(x=>`<p style="white-space:pre-line">${esc(x)}</p>`).join('')}<a class="text-link" href="${href('contact')}">${t('تواصلي معنا','Contact us')}</a></div></main>`}
function contact(){const phone=String(catalog.settings.business_phone||'').replace(/\D/g,'');return `<main id="main" class="wrap">${head(t('نسمعكِ بكل عناية','We’re here, thoughtfully'))}<div class="content"><h3>${t('المدينة المنورة، المملكة العربية السعودية','Madinah, Saudi Arabia')}</h3><p>${t('خدمات منزلية للسيدات. لا يوجد عنوان استقبال معلن.','At-home services for women. No walk-in location is advertised.')}</p>${phone?`<a class="btn sage" href="https://wa.me/${phone}" target="_blank" rel="noopener">${t('تواصلي عبر واتساب','Chat on WhatsApp')}</a>`:`<div class="notice">${t('بيانات التواصل قيد الإعداد من الإدارة. يمكنكِ تسجيل طلبكِ عبر نموذج الحجز.','Contact details are awaiting business setup. You can save a request through the booking form.')}</div>`}<a class="btn light" href="${href('booking')}">${t('طلب موعد','Request appointment')}</a><h3 style="margin-top:30px">${t('مناطق الخدمة','Service areas')}</h3><p>${catalog.settings.areas?.length?catalog.settings.areas.map(esc).join(' · '):t('تُحدد المناطق المعتمدة بواسطة الإدارة قبل التأكيد.','Approved neighborhoods will be configured by management before confirmation.')}</p></div></main>`}
function faq(){if(catalog.settings['faq_'+lang])return `<main id="main" class="wrap">${head(t('أجوبة بهدوء','A few thoughtful answers'))}<div class="content" style="white-space:pre-line">${esc(catalog.settings['faq_'+lang])}</div></main>`;return `<main id="main" class="wrap">${head(t('أجوبة بهدوء','A few thoughtful answers'))}<div class="content">${[[t('هل يتم تأكيد الحجز فوراً؟','Is my booking confirmed immediately?'),t('لا. يُحفظ الطلب بانتظار التأكيد ويتواصل الفريق معكِ شخصياً.','No. Your request is saved as pending and our team confirms it personally.')],[t('هل أحتاج حساباً للحجز؟','Do I need an account to book?'),t('يمكنكِ الحجز كزائرة. الحساب يساعدكِ على متابعة الحجوزات المرتبطة به والبتلات.','Guest booking is welcome. An account helps you follow linked bookings and petals.')],[t('متى أحصل على البتلات؟','When do I earn petals?'),t('بعد اكتمال الخدمة وتسجيل الدفع المتحقق منه، مع توثيق حسابكِ. تأكيد الحجز وحده لا يمنح نقاطاً.','After service completion and verified payment, with a verified account. Confirmation alone never awards points.')],[t('هل واتساب يرسل رسالتي تلقائياً؟','Does WhatsApp send my message automatically?'),t('لا. يفتح رابطاً برسالة جاهزة، وعليكِ الضغط على إرسال داخل واتساب.','No. A link opens a prepared message. You must press Send inside WhatsApp.')],[t('كيف أستعيد كلمة المرور؟','How do I reset my password?'),t('تواصلي مع الفريق من رقم واتساب المرتبط بحسابكِ. بعد التحقق يمنحكِ الفريق رابطاً قصير الصلاحية للاستخدام مرة واحدة.','Contact staff from the WhatsApp number associated with your account. After verification, staff can provide a short-lived, single-use reset link.')]].map(([q,a])=>`<details class="details"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></main>`}
function recovery(){return `<main id="main" class="wrap">${head(t('نساعدكِ على العودة','Let’s help you back in'))}<div class="content"><p>${t('تواصلي مع الفريق من محادثة واتساب المرتبطة برقم حسابكِ. بعد التحقق من هويتكِ يرسل الفريق رمزاً مؤقتاً يُستخدم مرة واحدة. لا تطلبي أو ترسلي كلمة مروركِ الحالية.','Contact staff through the WhatsApp conversation associated with your account number. Once your identity is verified, staff can manually send a short-lived, single-use reset token. Never share your current password.')}</p><a class="btn" href="${href('contact')}">${t('تواصلي مع الفريق','Contact the team')}</a> <a class="btn light" href="${href('reset')}">${t('لديّ رمز استعادة','I have a reset token')}</a></div></main>`}
function notFound(){return `<main id="main" class="wrap">${head(t('هذه الصفحة غير موجودة','This page isn’t here'))}<a class="btn" href="${href('home')}">${t('العودة للرئيسية','Back home')}</a></main>`}
function serviceArt(s,cls=''){return s.image&&(/^(\/[^/]|https:\/\/)/.test(s.image))?`<div class="art ${cls}"><img src="${esc(s.image)}" alt="${esc(name(s))}" loading="lazy" style="width:100%;height:100%;object-fit:cover"></div>`:art(s.category==='massage'?'spa':s.category,cls)}
const owner=()=>user?.role==='owner'||user?.role==='super_admin';
async function adminPage(){if(!user)return auth();if(!owner()&&user.role!=='employee')return `<main id="main" class="wrap">${head(t('الدخول مخصص للفريق','Staff access only'))}<p>${t('ليس لديكِ صلاحية عرض هذه الصفحة.','Your account does not have access to this page.')}</p></main>`;if(!admin)admin=await api('/admin');const tabs=[['overview','نظرة عامة','Overview'],['bookings','الحجوزات والتقويم','Bookings & calendar'],['customers','العميلات والتوثيق','Customers & verification'],['payments','المدفوعات','Payments'],['rewards','المكافآت والبتلات','Rewards & petals'],...(owner()?[['services','الخدمات','Services'],['packages','الباقات','Packages'],['reviews','الآراء','Reviews'],['settings','إعدادات الموقع','Website settings'],['staff','الفريق','Staff'],['audit','سجل التدقيق','Audit log']]:[])];return `<main id="main" class="wrap">${head(t('مساحة الفريق','The team space'),t('التأكيد والدفع والتوثيق تتم بواسطة موظفة مخولة فقط.','Confirmation, payment and verification are handled by authorized staff.'))}<div class="admin-grid"><aside class="admin-nav">${tabs.map(([id,a,e])=>`<button data-admin-tab="${id}" class="${adminTab===id?'active':''}">${t(a,e)}</button>`).join('')}<button id="logout">${t('تسجيل الخروج','Sign out')}</button></aside><div class="dashboard-content"><div id="admin-error" role="alert"></div>${adminContent()}</div></div></main>`}
function adminContent(){const a=admin;if(adminTab==='overview'){const b=a.bookings||[],analytics=a.analytics||{};return `<h2>${t('اليوم في J SPA','At J SPA')}</h2><div class="stats">${[[t('طلبات الحجز','Booking requests'),b.length],[t('بانتظار التأكيد','Pending'),b.filter(x=>x.status==='pending_confirmation').length],[t('مؤكدة','Confirmed'),b.filter(x=>x.status==='confirmed').length],[t('مكتملة','Completed'),b.filter(x=>x.status==='completed').length]].map(([l,v])=>`<div class="stat">${l}<b>${v}</b></div>`).join('')}</div>${owner()?`<h3>${t('ملخص فعلي','Actual recorded figures')}</h3>${simpleTable(Object.entries(analytics).map(([metric,value])=>({metric,value})),['metric','value'])}`:''}<div class="notice">${t('سجلات الدفع المتحقق منها فقط تمثل الإيراد المسجل. طلبات الحجز ليست إيراداً.','Only verified payment records represent recorded revenue. Booking requests are not revenue.')}</div><h3>${t('طلبات تحتاج مراجعة','Requests to review')}</h3>${adminBookings(b.filter(x=>x.status==='pending_confirmation'))}`}
if(adminTab==='bookings')return `<h2>${t('الحجوزات والتقويم','Bookings & calendar')}</h2><label class="field">${t('تصفية حسب التاريخ','Filter by date')}<input type="date" id="calendar-filter"></label><div id="booking-list">${adminBookings(a.bookings||[])}</div>`;
if(adminTab==='customers')return `<h2>${t('العميلات والتوثيق','Customers & verification')}</h2>${(a.customers||[]).map(c=>`<details class="details"><summary>${esc(c.name)} · <bdi>${esc(c.phone)}</bdi> · ${c.verified?t('موثق','Verified'):t('بانتظار التوثيق','Unverified')}</summary><form data-admin-form="verify"><input type="hidden" name="user_id" value="${c.id}">${field(t('مرجع التحقق من رسالة العميلة','Verification reference from customer message'),'reference','text','','required')}${field(t('رقم المرسلة الفعلي في واتساب','Actual WhatsApp sender number'),'observed_phone','tel','','required')}<label class="check"><input type="checkbox" name="checked" required><span>${t('تحققت من رقم المرسلة الفعلي ومطابقته لرقم الحساب والمرجع.','I checked the actual sender’s number and matched it to this account and reference.')}</span></label><button class="btn small">${t('اعتماد التوثيق','Approve verification')}</button></form><form data-admin-form="recovery"><h3>${t('استعادة الحساب بمساعدة الفريق','Staff-assisted account recovery')}</h3><input type="hidden" name="user_id" value="${c.id}">${field(t('رقم واتساب المتحقق منه','Verified WhatsApp sender number'),'observed_phone','tel','','required')}<label class="check"><input type="checkbox" name="checked" required><span>${t('تحققت من الهوية باستخدام المحادثة المعروفة للعميلة.','I verified identity through the customer’s established conversation.')}</span></label><button class="btn small light">${t('إنشاء رابط استعادة لمرة واحدة','Create single-use recovery link')}</button><div class="admin-result"></div></form></details>`).join('')||`<div class="empty">${t('لا توجد حسابات بعد.','No customer accounts yet.')}</div>`}`;
if(adminTab==='payments')return `<h2>${t('المدفوعات المسجلة','Recorded payments')}</h2><p class="muted">${t('سجلي الدفع المتحقق منه من تفاصيل الحجز.','Record verified payments through the booking details.')}</p>${simpleTable(a.payments||[],['booking_id','amount','payment_method','created_at'])}`;
if(adminTab==='rewards')return `<h2>${t('المكافآت والبتلات','Rewards & petals')}</h2>${(a.reward_requests||[]).map(r=>`<details class="details"><summary>${esc(r.id)} · ${esc(r.status)} · ${r.points} ${t('بتلة','petals')}</summary><form data-admin-form="rewards/${r.id}"><label class="field">${t('الحجز المؤهل','Eligible booking')}<select name="booking_id" required><option value="">${t('اختاري الحجز','Choose booking')}</option>${(a.bookings||[]).filter(b=>b.user_id===r.user_id).map(b=>`<option value="${b.id}">${esc(b.reference)} · ${money(b.total)}</option>`).join('')}</select></label><label class="field">${t('الإجراء','Action')}<select name="action"><option value="commit">${t('اعتماد وخصم النقاط','Commit and deduct points')}</option><option value="cancel">${t('إلغاء الطلب / رد النقاط','Cancel request / restore points')}</option></select></label><button class="btn small">${t('حفظ','Save')}</button></form></details>`).join('')||`<div class="empty">${t('لا توجد طلبات مكافآت.','No reward requests.')}</div>`}${ledgerTable(a.ledger)}${owner()?`<details class="details"><summary>${t('تعديل نقاط بصلاحية المالك','Owner point adjustment')}</summary><form data-admin-form="adjustment"><label class="field">${t('العميلة','Customer')}<select name="user_id">${(a.customers||[]).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${field(t('التعديل (موجب أو سالب)','Adjustment (positive or negative)'),'points','number','','required step="1"')}${field(t('السبب المكتوب','Written reason'),'reason','text','','required minlength="5"')}<button class="btn small">${t('تسجيل التعديل','Record adjustment')}</button></form></details>`:''}`;
if(adminTab==='services')return `<h2>${t('إدارة الخدمات','Manage services')}</h2>${(a.services||[]).map(s=>catalogEditor(s,'services')).join('')}${catalogEditor({},'services')}`;
if(adminTab==='packages')return `<h2>${t('إدارة الباقات','Manage packages')}</h2>${(a.packages||[]).map(p=>catalogEditor(p,'packages')).join('')}${catalogEditor({},'packages')}`;
if(adminTab==='reviews')return `<h2>${t('مراجعة تجارب العميلات','Review moderation')}</h2>${(a.reviews||[]).map(r=>`<article class="card"><div class="stars">${'★'.repeat(r.rating)}</div><p>${esc(r.body)}</p><p class="muted">${esc(r.display_name)} · ${r.approved?t('منشور','Published'):t('غير منشور','Unpublished')}</p><button class="btn small light" data-moderate="${r.id}" data-approved="${!r.approved}">${r.approved?t('إلغاء النشر','Unpublish'):t('اعتماد النشر','Approve publication')}</button></article>`).join('')||`<div class="empty">${t('لا توجد آراء للمراجعة.','No reviews to moderate.')}</div>`}`;
if(adminTab==='settings')return settingsForm();
if(adminTab==='staff')return `<h2>${t('إدارة الفريق','Staff management')}</h2>${(a.staff||[]).map(employee=>`<div class="card row"><span>${esc(employee.name)} · <bdi>${esc(employee.phone)}</bdi> · ${employee.role==='owner'?t('المالكة','Owner'):employee.role==='disabled_employee'?t('معطّل','Disabled'):t('موظفة','Employee')}</span>${employee.role==='owner'?'':`<form data-admin-form="staff/${employee.id}"><input type="hidden" name="action" value="${employee.role==='disabled_employee'?'enable':'disable'}"><button class="btn small light">${employee.role==='disabled_employee'?t('إعادة التفعيل','Enable access'):t('إيقاف الوصول','Disable access')}</button></form>`}</div>`).join('')}<form data-admin-form="staff" class="card"><h3>${t('إضافة موظفة','Add employee')}</h3>${field(t('الاسم','Name'),'name','text','','required')}${field(t('الجوال','Phone'),'phone','tel','','required')}${field(t('كلمة مرور مؤقتة قوية','Strong initial password'),'password','password','','required minlength="12"')}<input type="hidden" name="role" value="employee"><button class="btn">${t('إنشاء حساب الموظفة','Create employee account')}</button></form>`;
if(adminTab==='audit')return `<h2>${t('سجل التدقيق','Audit log')}</h2>${simpleTable(a.audit||[],['created_at','actor_id','action','details'])}`;return ''}
function adminBookings(rows){return rows.length?rows.sort((x,y)=>(x.date+x.time).localeCompare(y.date+y.time)).map(b=>`<details class="details"><summary><strong>${esc(b.reference)}</strong> · ${esc(b.name)} · ${esc(b.date)} ${esc(b.time)} · ${status(b.status)}</summary><p><bdi>${esc(b.phone)}</bdi> · ${esc(b.neighborhood)} · ${money(b.total)}</p><p class="muted">${(b.items||[]).map(x=>esc(name(x)||x.name)).join(' + ')} · ${minutes(b.duration)}</p><p>${esc(b.notes)}</p><a class="text-link" href="https://wa.me/${String(b.phone).replace(/\D/g,'').replace(/^0/,'966')}?text=${encodeURIComponent(t('مرحباً '+b.name+'، بخصوص طلبكِ '+b.reference+' لدى J SPA، نود تنسيق تفاصيل موعدكِ.','Hello '+b.name+', regarding your J SPA request '+b.reference+', we would like to coordinate your appointment.'))}" target="_blank" rel="noopener">${t('فتح محادثة العميلة (إرسال يدوي)','Open customer chat (manual send)')}</a><form data-admin-form="bookings/${b.id}"><div class="form-grid"><label class="field">${t('حالة الخدمة','Service status')}<select name="status">${['pending_confirmation','confirmed','in_progress','completed','cancelled','no_show'].map(s=>`<option value="${s}" ${b.status===s?'selected':''}>${status(s)}</option>`).join('')}</select></label>${field(t('التاريخ المتفق عليه','Agreed date'),'date','date',b.date,'required')}${field(t('الوقت المتفق عليه (الرياض)','Agreed time (Riyadh)'),'time','time',b.time,'required')}${field(t('المبلغ المدفوع الفعلي ر.س','Actual paid amount SAR'),'paid_amount','number',b.paid_amount??'','min="0" step="0.01"')}<label class="field">${t('طريقة الدفع','Payment method')}<select name="payment_method">${[['cash','نقداً','Cash'],['card','بطاقة / جهاز خارجي','Card / external POS'],['bank_transfer','تحويل بنكي','Bank transfer'],['other','أخرى','Other']].map(([v,ar,en])=>`<option value="${v}" ${b.payment_method===v?'selected':''}>${t(ar,en)}</option>`).join('')}</select></label></div><label class="check"><input type="checkbox" name="payment_verified" ${b.payment_verified?'checked':''}><span>${t('تحققت من استلام المبلغ الفعلي. هذا ليس إفادة دفع من العميلة.','I verified receipt of the actual payment. This is not a customer self-reported payment.')}</span></label><button class="btn small">${t('حفظ التحديث','Save update')}</button></form><form data-admin-form="bookings/${b.id}" data-refund="true"><h3>${t('تسجيل استرداد','Record refund')}</h3><div class="form-grid">${field(t('إجمالي المبلغ المسترد ر.س','Cumulative refunded amount SAR'),'refund_amount','number',(b.refund_cents||0)/100,'required min="0" step="0.01"')}${field(t('سبب الاسترداد','Refund reason'),'reason','text','','required')}</div><button class="btn small light">${t('حفظ الاسترداد وتسوية النقاط','Save refund and adjust points')}</button></form></details>`).join(''):`<div class="empty">${t('لا توجد حجوزات هنا بعد.','No bookings here yet.')}</div>`}
function catalogEditor(item,type){const service=type==='services';return `<details class="details"><summary>${item.id?esc(name(item)):t(service?'إضافة خدمة':'إضافة باقة',service?'Add service':'Add package')}</summary><form data-admin-form="${type}">${item.id?`<input type="hidden" name="id" value="${item.id}">`:''}<div class="form-grid">${field(t('الاسم العربي','Arabic name'),'name_ar','text',item.name_ar,'required')}${field(t('الاسم الإنجليزي','English name'),'name_en','text',item.name_en,'required')}${field(t('السعر ر.س','Price SAR'),'price','number',item.price,'required min="0" step="0.01"')}${service?`${field(t('المدة بالدقائق','Duration in minutes'),'duration','number',item.duration,'required min="5"')}<label class="field">${t('القسم','Category')}<select name="category">${[['massage','المساج','Massage'],['nails','الأظافر','Nails'],['gel','الجل','Gel']].map(([v,a,e])=>`<option value="${v}" ${item.category===v?'selected':''}>${t(a,e)}</option>`).join('')}</select></label><label class="field">${t('الوصف العربي','Arabic description')}<textarea name="description_ar" required>${esc(item.description_ar)}</textarea></label><label class="field">${t('الوصف الإنجليزي','English description')}<textarea name="description_en" required>${esc(item.description_en)}</textarea></label>${field(t('رابط صورة معتمدة اختيارية','Optional approved image URL'),'image','text',item.image||'')}<label class="check"><input type="checkbox" name="credentials_required" ${item.credentials_required?'checked':''}><span>${t('تتطلب مؤهلات مهنية معتمدة','Requires approved professional credentials')}</span></label><label class="check"><input type="checkbox" name="credentials_approved" ${item.credentials_approved?'checked':''}><span>${t('راجعت المؤهلات والاحتياطات واعتمدت تقديم الخدمة','I reviewed credentials and precautions and approved service delivery')}</span></label>`:`<div class="full"><label class="field">${t('الخدمات ضمن الباقة (اختيارات متعددة)','Included services (multiple selection)')}<select name="service_ids" multiple size="6" required>${(admin.services||[]).map(s=>`<option value="${s.id}" ${(item.service_ids||[]).map(String).includes(String(s.id))?'selected':''}>${esc(name(s))} · ${money(s.price)}</option>`).join('')}</select></label></div>`}</div><label class="check"><input type="checkbox" name="active" ${item.active!==false&&item.active!==0?'checked':''}><span>${t('عرض في الموقع','Visible on website')}</span></label>${!service&&item.id?`<label class="check"><input type="checkbox" name="remove"><span>${t('إزالة الباقة','Remove package')}</span></label>`:''}<button class="btn small">${t('حفظ','Save')}</button></form></details>`}
function settingsForm(){const s=admin.settings||{};return `<h2>${t('إعدادات الموقع والتشغيل','Website & operational settings')}</h2><form id="settings-form"><h3>${t('التواصل','Contact')}</h3><div class="form-grid">${field(t('رقم واتساب (9665xxxxxxxx)','WhatsApp number (9665xxxxxxxx)'),'business_phone','tel',s.business_phone)}${field('Instagram','instagram','url',s.instagram)}${field('TikTok','tiktok','url',s.tiktok)}</div><h3>${t('الجدول ومناطق الخدمة','Schedule & service areas')}</h3><div class="form-grid">${field(t('الطاقة الاستيعابية (0 غير معدة)','Simultaneous capacity (0 unconfigured)'),'capacity','number',s.capacity,'min="0" step="1" required')}${field(t('وقت الفتح','Opening time'),'opening_time','time',s.opening_time,'required')}${field(t('وقت الإغلاق','Closing time'),'closing_time','time',s.closing_time,'required')}${field(t('مدة التنقل بالدقائق','Travel buffer in minutes'),'travel_buffer','number',s.travel_buffer,'required min="0"')}${field(t('الحد الأدنى قبل الموعد بالساعات','Minimum lead time in hours'),'lead_hours','number',s.lead_hours,'required min="0"')}<label class="field">${t('أيام العمل','Working days')}<select name="working_days" multiple size="7">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}" ${(s.working_days||[]).includes(i)?'selected':''}>${t(['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'][i],d)}</option>`).join('')}</select></label><label class="field">${t('الأحياء (حي في كل سطر)','Neighborhoods (one per line)')}<textarea name="areas">${esc((s.areas||[]).join('\n'))}</textarea></label><label class="field">${t('الأيام المغلقة (YYYY-MM-DD في كل سطر)','Unavailable dates (YYYY-MM-DD, one per line)')}<textarea name="blocked_dates">${esc((s.blocked_dates||[]).join('\n'))}</textarea></label></div><h3>${t('قواعد نادي بتلات J','J Petals Club rules')}</h3>${field(t('نقاط لكل ريال مؤهل','Points per eligible SAR'),'points_per_sar','number',s.points_per_sar,'min="0" step="0.01" required')}<label class="field">${t('قواعد المكافآت: رمز | نقاط | قيمة ر.س، كل مكافأة في سطر','Rewards: ID | points | value SAR, one per line')}<textarea name="rewards">${esc((s.rewards||[]).map(r=>`${r.id} | ${r.points} | ${r.value}`).join('\n'))}</textarea></label><label class="check"><input type="checkbox" name="business_approved" ${s.business_approved?'checked':''}><span>${t('اعتمدت الإدارة بيانات الخدمات والأسعار والباقات للتشغيل.','Business has approved service data, prices and packages for operation.')}</span></label><div class="notice">${t('اعتماد الأسعار لا يعني اعتماداً قانونياً أو مهنياً. تأكدي من المؤهلات والموافقات قبل الإطلاق.','Price approval is not legal or professional approval. Confirm credentials and policies before launch.')}</div><button class="btn">${t('حفظ الإعدادات','Save settings')}</button><h3 style="margin-top:30px">${t('محتوى الموقع','Website content')}</h3>${['about','faq','policies','privacy','terms'].map(k=>`<details class="details"><summary>${({about:t('عن J','About'),faq:t('الأسئلة الشائعة','FAQ'),policies:t('سياسة الحجز','Booking policies'),privacy:t('الخصوصية','Privacy'),terms:t('الشروط','Terms')})[k]}</summary><div class="form-grid">${['ar','en'].map(l=>`<label class="field">${l==='ar'?'العربية':'English'}<textarea name="${k}_${l}" maxlength="15000" dir="${l==='ar'?'rtl':'ltr'}">${esc(s[k+'_'+l])}</textarea></label>`).join('')}</div></details>`).join('')}<button class="btn">${t('حفظ المحتوى والإعدادات','Save content & settings')}</button></form>`}
function bindAdmin(){document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.adminTab;render()});$('#calendar-filter')?.addEventListener('change',e=>{$('#booking-list').innerHTML=adminBookings((admin.bookings||[]).filter(b=>!e.target.value||b.date===e.target.value));bindAdminForms()});bindAdminForms();document.querySelectorAll('[data-moderate]').forEach(b=>b.onclick=async()=>{try{await api('/admin/reviews/'+b.dataset.moderate,{approved:b.dataset.approved==='true'});await refreshAdmin()}catch(e){toast(e.message)}});$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));for(const k of ['capacity','travel_buffer','lead_hours','points_per_sar'])d[k]=Number(d[k]);d.working_days=[...f.elements.working_days.selectedOptions].map(x=>Number(x.value));for(const k of ['areas','blocked_dates'])d[k]=d[k].split('\n').map(s=>s.trim()).filter(Boolean);d.business_approved=f.elements.business_approved.checked;try{d.rewards=d.rewards.split('\n').filter(s=>s.trim()).map(line=>{const [id,p,v]=line.split('|').map(s=>s.trim());if(!id||!Number.isFinite(Number(p))||!Number.isFinite(Number(v)))throw new Error(t('تنسيق المكافأة غير صحيح','Invalid reward format'));return {id,points:Number(p),value:Number(v)}});await api('/admin/settings',{settings:d});await refreshAdmin()}catch(err){toast(err.message)}})}
function bindAdminForms(){document.querySelectorAll('[data-admin-form]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),route=f.dataset.adminForm;for(const k of ['checked','active','remove','payment_verified','credentials_required','credentials_approved'])if(f.elements[k])d[k]=f.elements[k].checked;for(const k of ['price','duration','paid_amount','refund_amount','points'])if(d[k]!==undefined){if(d[k]==='')delete d[k];else d[k]=Number(d[k])}if(f.elements.service_ids)d.service_ids=[...f.elements.service_ids.selectedOptions].map(x=>x.value);if(route.startsWith('bookings/')&&!f.dataset.refund){const old=admin.bookings.find(x=>x.id===route.split('/')[1]);if(d.date===old?.date)delete d.date;if(d.time===old?.time)delete d.time}const b=e.submitter;b.disabled=true;try{const r=await api('/admin/'+route,d);if(route==='recovery'){f.querySelector('.admin-result').innerHTML=`<div class="success"><p>${t('انسخي الرابط وأرسليه يدوياً للعميلة المتحقق منها.','Copy the link and manually send it to the verified customer.')}</p><pre>${esc(r.reset_url?new URL(r.reset_url,location.origin).href:r.token)}</pre></div>`;b.disabled=false}else await refreshAdmin()}catch(err){toast(err.message);b.disabled=false}})}
async function refreshAdmin(){admin=null;catalog=await api('/catalog');toast(t('تم الحفظ','Saved'));await render()}
async function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';const p=page();let body;try{if(p==='home')body=home();else if(p==='services')body=services();else if(p.startsWith('services/'))body=detail(p.split('/')[1]);else if(p==='packages')body=`<main id="main" class="wrap">${head(t('لحظات متناغمة','Beautifully paired moments'))}${provisional()}<div class="grid two section" style="padding-top:0">${catalog.packages.map(packageCard).join('')}</div></main>`;else if(p==='booking'){const q=new URLSearchParams(location.search);if(q.has('service')&&bookingStep===1){draft.service_ids=[q.get('service')];draft.package_id=null}if(q.has('package')&&bookingStep===1){draft.package_id=q.get('package');draft.service_ids=[]}body=booking()}else if(['login','register','reset'].includes(p))body=auth(p);else if(['account','bookings','rewards'].includes(p))body=await accountPage(p);else if(p==='petals')body=`<main id="main" class="wrap">${head(t('العناية تُزهر','Care, in full bloom'))}${petalsContent()}</main>`;else if(p==='reviews')body=`<main id="main" class="wrap">${head(t('تجارب حقيقية','Real experiences'))}<section class="section" style="padding-top:0">${reviewsContent(catalog.reviews)}</section></main>`;else if(['about','privacy','terms','policies'].includes(p))body=contentPage(p);else if(p==='contact')body=contact();else if(p==='faq')body=faq();else if(p==='recovery')body=recovery();else if(p==='admin')body=await adminPage();else body=notFound()}catch(e){body=`<main id="main" class="wrap">${head(t('تعذر تحميل الصفحة','Unable to load this page'))}<div class="error">${esc(e.message)}</div><button class="btn" id="retry">${t('إعادة المحاولة','Try again')}</button></main>`}$('#app').innerHTML=header()+body+footer();document.title='J SPA | '+(p==='home'?t('سبا منزلي المدينة المنورة','Home Spa Madinah'):p.replaceAll('-',' '));bind()}
function bind(){document.querySelectorAll('a[href^="/'+lang+'/"]').forEach(a=>a.addEventListener('click',e=>{if(a.target||e.ctrlKey||e.metaKey)return;e.preventDefault();const u=new URL(a.href);history.pushState({},'',u.pathname+u.search);render();window.scrollTo(0,0)}));$('#menu')?.addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)});$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';history.replaceState({},'',href(page())+location.search);render()};$('#retry')?.addEventListener('click',render);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#auth-form')?.addEventListener('submit',authSubmit);$('#booking-form')?.addEventListener('submit',bookingSubmit);$('#back-step')?.addEventListener('click',()=>{saveDraft();bookingStep--;render()});document.querySelectorAll('[name=service]').forEach(i=>i.onchange=()=>{draft.service_ids=[...document.querySelectorAll('[name=service]:checked')].map(x=>x.value);draft.package_id=null;history.replaceState({},'',href('booking'));render()});document.querySelectorAll('[name=package]').forEach(i=>i.onchange=()=>{draft.package_id=i.value;draft.service_ids=[];history.replaceState({},'',href('booking'));render()});document.querySelectorAll('[data-booktype]').forEach(i=>i.onclick=()=>{if(i.dataset.booktype==='services'){draft.package_id=null}else{draft.service_ids=[];draft.package_id=catalog.packages[0]?.id}history.replaceState({},'',href('booking'));render()});$('#copy-message')?.addEventListener('click',()=>copy(bookingResult.message));$('#new-booking')?.addEventListener('click',()=>{bookingResult=null;bookingStep=1;draft={service_ids:[],package_id:null,date:'',time:'',name:'',phone:'',neighborhood:'',notes:'',terms:false,idempotency_key:crypto.randomUUID()};history.replaceState({},'',href('booking'));render();window.scrollTo(0,0)});$('#logout')?.addEventListener('click',async()=>{await api('/logout',{});account=null;admin=null;await session();go('home')});$('#verify-request')?.addEventListener('click',verification);document.querySelectorAll('[data-reward]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await api('/rewards/request',{reward_id:b.dataset.reward});account=null;toast(t('تم تسجيل طلب المكافأة','Reward request saved'));render()}catch(e){toast(e.message);b.disabled=false}});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewDialog(b.dataset.review));bindAdmin()}
async function copy(s){try{await navigator.clipboard.writeText(s);toast(t('تم النسخ','Copied'))}catch{toast(t('يمكنكِ تحديد النص ونسخه يدوياً.','Select and copy the message manually.'))}}
function saveDraft(){const f=$('#booking-form');if(!f)return;for(const k of ['date','time','name','phone','neighborhood','notes'])if(f.elements[k])draft[k]=f.elements[k].value;if(f.elements.terms)draft.terms=f.elements.terms.checked}
async function bookingSubmit(e){e.preventDefault();saveDraft();if(bookingStep===1&&!selected().items.length){$('#form-error').innerHTML=`<div class="error">${t('اختاري خدمة أو باقة.','Please choose a service or package.')}</div>`;return}if(bookingStep<4){bookingStep++;render();return}const b=e.submitter;b.disabled=true;try{bookingResult=await api('/bookings',draft);account=null;render();window.scrollTo(0,0)}catch(err){$('#form-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;b.disabled=false}}
async function authSubmit(e){e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form)),mode=form.dataset.mode;data.terms=!!form.elements.terms?.checked;e.submitter.disabled=true;try{await api('/'+mode,data);await session();account=null;admin=null;if(mode==='reset'){toast(t('تم تحديث كلمة المرور. سجلي الدخول.','Password updated. Please sign in.'));go('login')}else go(user?.role==='owner'||user?.role==='employee'?'admin':'account')}catch(err){$('#form-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;e.submitter.disabled=false}}
async function verification(){try{const r=await api('/verification/request',{});$('#verification-result').innerHTML=`<div class="success"><p>${t('مرجع التحقق','Verification reference')}: <bdi>${esc(r.reference)}</bdi></p><p>${t('ينتهي في','Expires')}: ${esc(r.expires_at)}</p>${r.whatsapp_url?`<a class="btn sage small" href="${esc(r.whatsapp_url)}" target="_blank" rel="noopener">${t('افتحي واتساب واضغطي إرسال','Open WhatsApp, then press Send')}</a>`:`<p>${t('رقم واتساب غير معد بعد. تواصلي مع الإدارة عند توفر بيانات التواصل.','The business WhatsApp number is not configured yet. Contact management when details are available.')}</p>`}</div>`}catch(e){toast(e.message)}}
function dialog(content){$('#modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog id="modal"><button class="btn light small" id="close-dialog" style="float:inline-end">${t('إغلاق','Close')}</button>${content}</dialog>`);$('#modal').showModal();$('#close-dialog').onclick=()=>$('#modal').close()}
function reviewDialog(id){dialog(`<h2>${t('كيف كانت لحظتكِ؟','How was your moment?')}</h2><form id="review-form"><label class="field">${t('التقييم','Rating')}<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label>${field(t('اسم العرض (اختياري)','Public display name (optional)'),'display_name','text','','maxlength="60"')}<label class="field">${t('تجربتكِ','Your experience')}<textarea name="body" required maxlength="2000"></textarea></label><p class="muted">${t('لا تكتبي رقم الجوال أو العنوان أو معلومات خاصة. تخضع الآراء للمراجعة قبل النشر.','Do not include phone numbers, addresses or private details. Reviews are moderated before publication.')}</p><button class="btn">${t('إرسال للمراجعة','Submit for moderation')}</button></form>`);$('#review-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('/reviews',{...d,booking_id:id,rating:Number(d.rating)});$('#modal').close();account=null;toast(t('شكراً لمشاركة تجربتكِ','Thank you for sharing'));render()}catch(err){toast(err.message)}}}
window.addEventListener('popstate',render);
(async()=>{try{await session();catalog=await api('/catalog');render()}catch(e){$('#app').innerHTML=`<main class="wrap">${head('J SPA')}<div class="error">${esc(e.message)}</div><p>${t('تعذر الاتصال بالخادم. أعيدي تحميل الصفحة.','Unable to connect to the server. Please reload.')}</p></main>`}})();
